304	func listDeleteUserInboxIDs(ctx context.Context, tx *sql.Tx, userID int32, memoIDSet map[int32]struct{}) ([]int32, error) {
305		directIDs, err := listDeleteUserDirectInboxIDs(ctx, tx, userID)
306		if err != nil {
307			return nil, err
308		}
309		inboxIDs := append([]int32{}, directIDs...)
310		if len(memoIDSet) == 0 {
311			return inboxIDs, nil
312		}
313	
314		memoIDs, err := listDeleteUserMemoReferencedInboxIDs(ctx, tx, userID, memoIDSet)
315		if err != nil {
316			return nil, err
317		}
318		return append(inboxIDs, memoIDs...), nil
319	}
