557	func attachmentIDsFromList(attachments []*store.Attachment) []int32 {
558		ids := make([]int32, 0, len(attachments))
559		for _, attachment := range attachments {
560			if attachment == nil {
561				continue
562			}
563			ids = append(ids, attachment.ID)
